        self.delegate = None  # Explicit delegate assignment

    def assign_delegate(self, delegate):
        self.delegate = delegate  # Assign delegate explicitly

    def execute_task(self):
        if self.delegate:
            self.delegate.perform_task()  # Delegate execution
        else:
            print("No delegate assigned.")

# Usage
